add_action( 'woocommerce_edit_account_form', 'perfectpixel_account_user_field' );
add_action( 'woocommerce_save_account_details', 'perfectpixel_account_user_field_save' );

function perfectpixel_account_user_field_key() {
	$key = sanitize_key( '{{account_user_field_key}}' );
	// Never let customers edit roles, capabilities or session data.
	foreach ( array( 'capabilities', 'user_level', 'session_tokens', 'user_pass', 'user_login', 'user_email', 'user_status', 'user_activation_key' ) as $blocked ) {
		if ( false !== strpos( $key, $blocked ) ) {
			return '';
		}
	}
	return $key;
}

function perfectpixel_account_user_field() {
	$key = perfectpixel_account_user_field_key();
	if ( ! $key ) {
		return;
	}
	$user  = wp_get_current_user();
	$value = 'user_url' === $key ? $user->user_url : get_user_meta( $user->ID, $key, true );
	printf(
		'<p class="woocommerce-form-row form-row form-row-wide"><label for="perfectpixel_user_field">%s</label><input type="%s" class="woocommerce-Input input-text" name="perfectpixel_user_field" id="perfectpixel_user_field" value="%s"></p>',
		esc_html( '{{account_user_field_label}}' ),
		'user_url' === $key ? 'url' : 'text',
		esc_attr( is_scalar( $value ) ? $value : '' )
	);
}

function perfectpixel_account_user_field_save( $user_id ) {
	$key = perfectpixel_account_user_field_key();
	if ( ! $key || ! isset( $_POST['perfectpixel_user_field'] ) ) {
		return;
	}
	$value = wp_unslash( $_POST['perfectpixel_user_field'] );
	if ( 'user_url' === $key ) {
		wp_update_user( array( 'ID' => $user_id, 'user_url' => esc_url_raw( $value ) ) );
	} else {
		update_user_meta( $user_id, $key, sanitize_text_field( $value ) );
	}
}
